import {ROLES,classifyRaster,replaceSimilarColor,validateReference} from './image-blueprint.js';
import {World} from './world.js';
import {Renderer} from './renderer.js';
import {encodeSchematic,gzip} from './nbt.js';

export function createImageBlueprintUI({modal,toast,onAsset,onReference}){
 const show=()=>{
  const body=document.createElement('div');body.innerHTML=`<p>Revise a classificação pintando sobre a imagem. Plantas orientam o traçado; alturas, fachadas e interiores são gerados por regras. Perspectivas geram uma fachada 2,5D: lados ocultos não são reconstruídos.</p><label>Imagem PNG, JPEG ou WebP (até 10 MB)<input id="blue-file" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="two-cols"><label>Entrada<select id="blue-mode"><option value="plan">Planta / mapa visto de cima</option><option value="facade">Perspectiva → fachada 2,5D</option></select></label><label>Classificação inicial<select id="blue-preset"><option value="city">Planta de cidade por cores</option><option value="map">Mapa Aincrad: contorno ciano</option><option value="facade">Toda a imagem</option></select></label></div><p class="field-help">Cidade: vermelho/escuro = construção, cinza = rua, verde = floresta, azul = água. Mapas com legendas e textos exigem limpeza manual. Na fachada, pinte o fundo como vazio.</p><div class="two-cols"><label>Pincel<select id="blue-role">${Object.entries(ROLES).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label><label>Raio em pixels<input id="blue-radius" type="number" min="1" max="32" value="3"></label></div><label class="checkbox-line"><input id="blue-color" type="checkbox"> Classificar toda cor semelhante ao clicar (tolerância 48)</label><button id="blue-reset" class="button secondary">Reclassificar imagem</button> <button id="blue-undo" class="button secondary">Desfazer pintura</button><canvas id="blue-map" width="512" height="256" style="width:100%;max-height:360px;object-fit:contain;touch-action:none;background:#14222e"></canvas><div class="three-cols"><label>Largura X<input id="blue-width" type="number" min="1" max="512" value="128"></label><label>Comprimento Z / altura da fachada<input id="blue-depth" type="number" min="1" max="512" value="128"></label><label>Altura dos prédios / profundidade da fachada<input id="blue-height" type="number" min="4" max="96" value="16"></label></div><label>Estilo dos volumes<select id="blue-style"><option value="aincrad">Pedra e telhados Aincrad</option><option value="wood">Madeira</option><option value="modern">Moderno</option></select></label><p class="field-help">Esta prévia tem até 2.097.152 posições. Para cidades grandes, envie o traçado para Mundos grandes e escolha 4048, 4096 ou outro tamanho. A exportação da cidade será dividida em peças .schem.</p><button id="blue-generate" class="button primary">Gerar prévia 3D</button> <button id="blue-world" class="button secondary">Usar traçado no mapa central</button><p id="blue-status" aria-live="polite">Selecione uma imagem.</p><canvas id="blue-preview" width="700" height="320" style="width:100%;height:320px;background:#111d29" hidden></canvas><button id="blue-library" class="button secondary" disabled>Adicionar à biblioteca</button> <button id="blue-download" class="button secondary" disabled>Baixar .schem</button>`;
  modal('Construções e mapas por imagem',body);const q=s=>body.querySelector(s),dialog=document.querySelector('#dialog');let pixels=null,roles=null,iw=0,ih=0,name='',result=null,worker=null,renderer=null,history=[],revision=0,timer=null;
  const status=t=>q('#blue-status').textContent=t,fail=e=>status(e.message||String(e));
  const invalidate=()=>{revision++;result=null;q('#blue-library').disabled=true;q('#blue-download').disabled=true;};
  const paint=()=>{if(!pixels)return;const c=q('#blue-map');c.width=iw;c.height=ih;const data=new Uint8ClampedArray(pixels);for(let i=0;i<roles.length;i++){const col=ROLES[roles[i]].color;for(let k=0;k<3;k++)data[i*4+k]=Math.round(data[i*4+k]*.45+parseInt(col.slice(1+k*2,3+k*2),16)*.55);data[i*4+3]=255;}c.getContext('2d').putImageData(new ImageData(data,iw,ih),0,0);};
  q('#blue-file').onchange=async()=>{try{const f=q('#blue-file').files[0];if(!f)return;if(f.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Use PNG, JPEG ou WebP de até 10 MB.');const image=await createImageBitmap(f);try{if(image.width*image.height>20000000)throw Error('Imagem acima de 20 milhões de pixels.');const scale=Math.min(1,1024/Math.max(image.width,image.height));iw=Math.max(1,Math.round(image.width*scale));ih=Math.max(1,Math.round(image.height*scale));const c=document.createElement('canvas');c.width=iw;c.height=ih;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,iw,ih);pixels=ctx.getImageData(0,0,iw,ih).data;name=f.name;roles=classifyRaster(pixels,iw,ih,q('#blue-preset').value);history=[];q('#blue-depth').value=Math.max(1,Math.round(128*ih/iw));invalidate();paint();status(`${name} · ${iw} × ${ih}. Revise o traçado antes de gerar.`);}finally{image.close();}}catch(e){fail(e);}};
  q('#blue-reset').onclick=()=>{if(!pixels)return;history.push(roles.slice());roles=classifyRaster(pixels,iw,ih,q('#blue-preset').value);invalidate();paint();};q('#blue-undo').onclick=()=>{if(history.length){roles=history.pop();invalidate();paint();}};
  const c=q('#blue-map');let drawing=false;
  const stroke=e=>{const r=c.getBoundingClientRect(),scale=Math.min(r.width/iw,r.height/ih),ox=(r.width-iw*scale)/2,oy=(r.height-ih*scale)/2,x=Math.floor((e.clientX-r.left-ox)/scale),z=Math.floor((e.clientY-r.top-oy)/scale);if(x<0||z<0||x>=iw||z>=ih)return;const role=Number(q('#blue-role').value);if(q('#blue-color').checked)replaceSimilarColor(roles,pixels,x+z*iw,role);else{const radius=Math.max(1,Math.min(32,Number(q('#blue-radius').value)));for(let dz=-radius;dz<=radius;dz++)for(let dx=-radius;dx<=radius;dx++)if(dx*dx+dz*dz<=radius*radius&&x+dx>=0&&x+dx<iw&&z+dz>=0&&z+dz<ih)roles[x+dx+(z+dz)*iw]=role;}invalidate();paint();};
  c.onpointerdown=e=>{if(!roles)return;history.push(roles.slice());if(history.length>5)history.shift();drawing=true;c.setPointerCapture(e.pointerId);stroke(e);};c.onpointermove=e=>{if(drawing&&!q('#blue-color').checked)stroke(e);};c.onpointerup=c.onpointercancel=()=>drawing=false;
  for(const id of ['mode','width','depth','height','style'])q('#blue-'+id).onchange=()=>{invalidate();q('#blue-world').disabled=q('#blue-mode').value==='facade';};
  const reference=()=>{if(!roles)throw Error('Selecione uma imagem.');return validateReference({version:1,name,width:iw,height:ih,roles:Array.from(roles),buildingHeight:Number(q('#blue-height').value),style:q('#blue-style').value,noiseBlend:0});};
  q('#blue-world').onclick=async()=>{try{const r=reference();dialog.close();await onReference(r);}catch(e){fail(e);}};
  q('#blue-generate').onclick=()=>{try{if(!pixels)throw Error('Selecione uma imagem.');worker?.terminate();clearTimeout(timer);const ticket=revision,facade=q('#blue-mode').value==='facade';worker=new Worker('./image-schem-worker.js',{type:'module'});status('Gerando blocos em segundo plano…');timer=setTimeout(()=>{worker?.terminate();status('Geração interrompida após 30 segundos. Reduza as dimensões.');},30000);worker.onerror=e=>{clearTimeout(timer);fail(e);worker?.terminate();};worker.onmessage=e=>{clearTimeout(timer);worker?.terminate();if(ticket!==revision)return;if(!e.data.ok){fail(e.data.error);return;}result=World.from(e.data.snapshot);q('#blue-download').disabled=false;try{renderer?.dispose();q('#blue-preview').hidden=false;renderer=new Renderer(q('#blue-preview'),()=>{});renderer.setWorld(result);renderer.reset();q('#blue-library').disabled=false;status(`${result.w} × ${result.h} × ${result.d} blocos. ${facade?'Fachada extrudada; não é cidade 3D reconstruída.':'Volumes estimados a partir do traçado revisado.'}`);}catch(err){fail(Error('Schematic gerado, mas prévia excede o limite: '+err.message));}};worker.postMessage(facade?{kind:'facade',rgba:pixels,imageWidth:iw,imageHeight:ih,options:{width:Number(q('#blue-width').value),height:Number(q('#blue-depth').value),depth:Number(q('#blue-height').value),mask:roles}}:{kind:'plan',reference:reference(),options:{width:Number(q('#blue-width').value),depth:Number(q('#blue-depth').value)}});}catch(e){fail(e);}};
  q('#blue-library').onclick=async()=>{try{if(!result)return;await onAsset(result,name+' · imagem');toast('Construção adicionada à biblioteca.');}catch(e){fail(e);}};
  q('#blue-download').onclick=async()=>{try{if(!result)return;const url=URL.createObjectURL(new Blob([await gzip(encodeSchematic(result))])),a=document.createElement('a');a.href=url;a.download='aincrad-imagem.schem';a.click();setTimeout(()=>URL.revokeObjectURL(url),20000);}catch(e){fail(e);}};
  dialog.addEventListener('close',()=>{worker?.terminate();clearTimeout(timer);renderer?.dispose();},{once:true});
 };
 for(const target of ['#import-schem','#large-worlds']){const b=document.createElement('button');b.className='button secondary full';b.style.marginTop='8px';b.textContent='◈ Criar mapa / construção por imagem';b.onclick=show;document.querySelector(target)?.after(b);}
 return {show};
}
